mapper.select:
SELECT * FROM ( SELECT EXEC_ID AS execId, BATCH_ID AS batchId, TO_CHAR(BASE_DT, 'YYYY-MM-DD') AS baseDt, TO_CHAR(START_AT, 'YYYY-MM-DD HH24:MI:SS') AS startAt, TO_CHAR(END_AT, 'YYYY-MM-DD HH24:MI:SS') AS endAt, STATUS AS status, TOTAL_CNT AS totalCnt, SUCCESS_CNT AS successCnt, FAIL_CNT AS failCnt, ERROR_MSG AS errorMsg FROM TB_BATCH_EXEC_LOG WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR}
AND BASE_DT = TO_DATE(#{baseDt,jdbcType=VARCHAR}, 'YYYY-MM-DD')
ORDER BY START_AT DESC ) WHERE ROWNUM = 1
